'use strict';

const APP_VERSION = '1.0.0';
const DB_VERSION = 1;
const DB_NAME = 'CasesManagerDB';
const DEVICE_ID_KEY = 'casesManagerDeviceId';
const DEFAULT_ACTION_TYPES = ['مخاطبة','تصرف نيابة','إرسال','استلام','فحص','أخرى'];
const DEFAULT_CASE_TYPES = ['عام'];
const STORE_NAMES = ['settings','sectors','caseTypes','actionTypes','cases','parties','sessions','actions','attachments','reminders','timeline','audit','trash'];
const entityStores = ['sectors','caseTypes','actionTypes','cases','parties','sessions','actions','reminders','timeline'];

let db;
let appState = { view:'dashboard', sectorId:null, caseId:null, tab:'overview', search:'', desktop:false, desktopInfo:null };
let cryptoKey = null;
let notificationTimer = null;
let swReg = null;
const $ = (s,r=document)=>r.querySelector(s);
const $$ = (s,r=document)=>Array.from(r.querySelectorAll(s));
const esc = s => String(s ?? '').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const nowISO = () => new Date().toISOString();
const uid = () => (crypto.randomUUID ? crypto.randomUUID() : 'id-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2));
const fmtDate = v => v ? new Intl.DateTimeFormat('ar-EG',{year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(v.length===10 ? v+'T12:00:00' : v)) : '—';
const fmtDateTime = v => v ? new Intl.DateTimeFormat('ar-EG',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}).format(new Date(v)) : '—';
const bytesFmt = n => { if(!Number.isFinite(n)) return ''; const u=['B','KB','MB','GB']; let i=0; while(n>=1024&&i<u.length-1){n/=1024;i++;} return `${n.toFixed(i?1:0)} ${u[i]}`; };
const deviceId = (()=>{let x=localStorage.getItem(DEVICE_ID_KEY); if(!x){x=uid();localStorage.setItem(DEVICE_ID_KEY,x);} return x;})();

function toast(msg,type=''){ const d=document.createElement('div'); d.className='toast '+type; d.textContent=msg; $('#toast-root').appendChild(d); setTimeout(()=>d.remove(),3500); }
function normalize(s){ return String(s??'').trim().toLowerCase().normalize('NFKD'); }
function downloadBlob(blob,name){ const a=document.createElement('a'); const u=URL.createObjectURL(blob); a.href=u;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),4000); }
function b64FromBuf(buf){ const b=new Uint8Array(buf); let s=''; for(let i=0;i<b.length;i+=0x8000)s+=String.fromCharCode(...b.subarray(i,i+0x8000)); return btoa(s); }
function bufFromB64(s){ const raw=atob(s); const b=new Uint8Array(raw.length); for(let i=0;i<raw.length;i++)b[i]=raw.charCodeAt(i); return b.buffer; }
function deepComparable(obj){ const c=structuredClone(obj); delete c.createdAt; delete c.updatedAt; delete c.updatedBy; delete c.rev; return JSON.stringify(c); }
function localDateInputValue(d=new Date()){ const off=d.getTimezoneOffset(); return new Date(d.getTime()-off*60000).toISOString().slice(0,16); }
function slugName(s){ return String(s||'ملف').replace(/[\\/:*?"<>|]+/g,'_').trim() || 'ملف'; }

function openDB(){ return new Promise((resolve,reject)=>{ const req=indexedDB.open(DB_NAME,DB_VERSION); req.onupgradeneeded=e=>{ const d=e.target.result; const ensure=(n,keyPath='id')=>{if(!d.objectStoreNames.contains(n)) d.createObjectStore(n,{keyPath});}; ensure('settings','key'); for(const n of STORE_NAMES.filter(x=>x!=='settings')) ensure(n); }; req.onsuccess=()=>resolve(req.result); req.onerror=()=>reject(req.error); }); }
function tx(store,mode='readonly'){ return db.transaction(store,mode).objectStore(store); }
function getOne(store,key){ return new Promise((resolve,reject)=>{ const r=tx(store).get(key); r.onsuccess=()=>resolve(r.result); r.onerror=()=>reject(r.error); }); }
function getAll(store){ return new Promise((resolve,reject)=>{ const r=tx(store).getAll(); r.onsuccess=()=>resolve(r.result||[]); r.onerror=()=>reject(r.error); }); }
function put(store,obj){ return new Promise((resolve,reject)=>{ const r=tx(store,'readwrite').put(obj); r.onsuccess=()=>resolve(obj); r.onerror=()=>reject(r.error); }); }
function del(store,key){ return new Promise((resolve,reject)=>{ const r=tx(store,'readwrite').delete(key); r.onsuccess=()=>resolve(); r.onerror=()=>reject(r.error); }); }
async function settingsGet(key,def=null){ return (await getOne('settings',key))?.value ?? def; }
async function settingsSet(key,value){ return put('settings',{key,value}); }
async function touch(rec){ rec.updatedAt=nowISO(); rec.updatedBy=deviceId; rec.rev=(rec.rev||0)+1; return rec; }
async function saveEntity(store,obj,{audit=true}={}){ if(!obj.id)obj.id=uid(); if(!obj.createdAt)obj.createdAt=nowISO(); await touch(obj); await put(store,obj); if(audit) await addAudit(store,obj.id,'save'); return obj; }
async function addAudit(store,entityId,action,details=''){ await put('audit',{id:uid(),store,entityId,action,details,at:nowISO(),deviceId}); }
async function softDelete(store,obj){ await put('trash',{id:uid(),store,entityId:obj.id,data:obj,deletedAt:nowISO(),deviceId}); await del(store,obj.id); await addAudit(store,obj.id,'delete'); }

async function initCrypto(){ let raw=await settingsGet('cryptoKey'); if(!raw){ const k=await crypto.subtle.generateKey({name:'AES-GCM',length:256},true,['encrypt','decrypt']); const ab=await crypto.subtle.exportKey('raw',k); raw=b64FromBuf(ab); await settingsSet('cryptoKey',raw); } cryptoKey=await crypto.subtle.importKey('raw',bufFromB64(raw),'AES-GCM',true,['encrypt','decrypt']); }
async function encryptBuffer(buffer,key=cryptoKey){ const iv=crypto.getRandomValues(new Uint8Array(12)); const data=await crypto.subtle.encrypt({name:'AES-GCM',iv},key,buffer); return {iv:b64FromBuf(iv.buffer),data}; }
async function decryptAttachment(att,key=cryptoKey){ return crypto.subtle.decrypt({name:'AES-GCM',iv:new Uint8Array(bufFromB64(att.iv))},key,att.data); }
async function sha256(buffer){ const h=await crypto.subtle.digest('SHA-256',buffer); return Array.from(new Uint8Array(h)).map(x=>x.toString(16).padStart(2,'0')).join(''); }

async function firstRun(){
  if(!await settingsGet('initialized')){
    await settingsSet('initialized',true);
    await settingsSet('appVersion',APP_VERSION);
    await settingsSet('schemaVersion',DB_VERSION);
    for(let i=0;i<DEFAULT_ACTION_TYPES.length;i++) await saveEntity('actionTypes',{id:`default-action-${i+1}`,name:DEFAULT_ACTION_TYPES[i]},{audit:false});
    for(let i=0;i<DEFAULT_CASE_TYPES.length;i++) await saveEntity('caseTypes',{id:`default-case-${i+1}`,name:DEFAULT_CASE_TYPES[i]},{audit:false});
  }
}

async function desktopDetect(){
  try{ const r=await fetch('./api/desktop/info',{cache:'no-store'}); if(r.ok){appState.desktop=true;appState.desktopInfo=await r.json();} }catch(_){appState.desktop=false;}
}

async function initPWA(){
  if('serviceWorker' in navigator){ try{ swReg=await navigator.serviceWorker.register('./sw.js'); }catch(e){console.warn(e);} }
}

function routeFromHash(){ const h=location.hash.replace(/^#/,''); if(h.startsWith('case/')){appState.view='case';appState.caseId=h.split('/')[1];} }
window.addEventListener('hashchange',()=>{routeFromHash();render();});

async function boot(){
  db=await openDB(); await initCrypto(); await firstRun(); await desktopDetect(); await initPWA(); routeFromHash();
  render(); startReminderWatcher();
}

async function getContext(){
  const [sectors,cases,parties,sessions,actions,attachments,reminders,caseTypes,actionTypes,timeline]=await Promise.all([
    getAll('sectors'),getAll('cases'),getAll('parties'),getAll('sessions'),getAll('actions'),getAll('attachments'),getAll('reminders'),getAll('caseTypes'),getAll('actionTypes'),getAll('timeline')
  ]);
  return {sectors,cases,parties,sessions,actions,attachments,reminders,caseTypes,actionTypes,timeline};
}

async function lastStepForCase(caseId,ctx){
  const arr=[];
  for(const a of ctx.actions.filter(x=>x.caseId===caseId)) arr.push({date:a.date||a.createdAt,label:`${a.typeName||'إجراء'}: ${a.summary||''}`});
  for(const s of ctx.sessions.filter(x=>x.caseId===caseId)) arr.push({date:s.dateTime||s.date||s.createdAt,label:`جلسة: ${s.summary||s.result||''}`});
  for(const t of ctx.timeline.filter(x=>x.caseId===caseId)) arr.push({date:t.at,label:t.title||t.detail||'تحديث'});
  arr.sort((a,b)=>new Date(b.date)-new Date(a.date)); return arr[0]||null;
}
function nextSession(caseId,ctx){ return ctx.sessions.filter(x=>x.caseId===caseId && new Date(x.dateTime||x.date)>new Date()).sort((a,b)=>new Date(a.dateTime||a.date)-new Date(b.dateTime||b.date))[0]||null; }
function sectorName(id,ctx){return ctx.sectors.find(x=>x.id===id)?.name||'—';}
function caseTypeName(id,ctx){return ctx.caseTypes.find(x=>x.id===id)?.name||'—';}
function statusText(s){return s==='closed'?'منتهية':s==='archived'?'مؤرشفة':'مفتوحة';}

function topbar(){ return `<div class="topbar">
  <div class="brand" onclick="goDashboard()"><div class="brand-mark">ق</div><div><h1>نظام متابعة القضايا</h1><small>الإصدار ${APP_VERSION} • قاعدة ${DB_VERSION}</small></div></div>
  <div class="search-wrap"><input id="global-search" class="search" placeholder="بحث برقم القضية، الموضوع، الطرف، المرفق..." value="${esc(appState.search)}"></div>
  <div class="top-actions">
    <button class="btn" onclick="showSettings()">⚙️ <span>الإعدادات</span></button>
    <button class="btn" onclick="showBackup()">💾 <span>النسخ والدمج</span></button>
    <button class="btn primary" onclick="showCaseForm()">＋ <span>قضية جديدة</span></button>
  </div>
</div>`; }

async function render(){
  const app=$('#app'); app.innerHTML=`<div class="app-shell">${topbar()}<main class="content"><div class="empty">جارٍ التحميل...</div></main></div>`;
  $('#global-search')?.addEventListener('input',e=>{appState.search=e.target.value; clearTimeout(window.__srch); window.__srch=setTimeout(render,180);});
  const ctx=await getContext(); let html='';
  if(appState.search.trim()) html=await renderSearch(ctx);
  else if(appState.view==='sector') html=await renderSector(ctx);
  else if(appState.view==='case') html=await renderCase(ctx);
  else html=await renderDashboard(ctx);
  $('.content').innerHTML=html;
  bindPostRender(ctx);
}

function bindPostRender(ctx){
  $$('.tab').forEach(b=>b.onclick=()=>{appState.tab=b.dataset.tab;render();});
}
window.goDashboard=()=>{appState={...appState,view:'dashboard',sectorId:null,caseId:null,tab:'overview',search:''};location.hash='';render();};
window.openSector=id=>{appState.view='sector';appState.sectorId=id;appState.search='';render();};
window.openCase=id=>{appState.view='case';appState.caseId=id;appState.tab='overview';appState.search='';location.hash=`case/${id}`;render();};

async function renderDashboard(ctx){
  const open=ctx.cases.filter(x=>x.status==='open'), closed=ctx.cases.filter(x=>x.status==='closed');
  const upcomingSessions=ctx.sessions.filter(s=>new Date(s.dateTime||s.date)>new Date()).sort((a,b)=>new Date(a.dateTime||a.date)-new Date(b.dateTime||b.date));
  const upcomingRem=ctx.reminders.filter(r=>!r.done && new Date(r.at)>new Date()).sort((a,b)=>new Date(a.at)-new Date(b.at));
  const overdue=ctx.reminders.filter(r=>!r.done && new Date(r.at)<=new Date());
  const rows=[];
  for(const c of open){const last=await lastStepForCase(c.id,ctx); const ns=nextSession(c.id,ctx); rows.push({...c,last,ns});}
  rows.sort((a,b)=>new Date(b.last?.date||b.updatedAt)-new Date(a.last?.date||a.updatedAt));
  return `<div class="page-head"><div><h2>لوحة المتابعة</h2><p>ملخص شامل لحالة القضايا والجلسات والتذكيرات</p></div><div class="row"><button class="btn" onclick="showSectorEditor()">تعديل الجهات</button><button class="btn" onclick="requestNotifyPermission()">🔔 تفعيل الإشعارات</button></div></div>
  <div class="grid stats">
    ${stat('إجمالي القضايا',ctx.cases.length,'كل القطاعات')}${stat('القضايا المفتوحة',open.length,'تحتاج متابعة','red')}${stat('القضايا المنتهية',closed.length,'مغلقة للقراءة','green')}
    ${stat('الجلسات القادمة',upcomingSessions.length,upcomingSessions[0]?`الأقرب ${fmtDateTime(upcomingSessions[0].dateTime||upcomingSessions[0].date)}`:'لا توجد','orange')}
    ${stat('التذكيرات القادمة',upcomingRem.length,upcomingRem[0]?fmtDateTime(upcomingRem[0].at):'لا توجد')}${stat('متأخرات',overdue.length,'تذكيرات لم تُنجز',overdue.length?'red':'')}
  </div>
  <div class="grid sectors">${ctx.sectors.length?ctx.sectors.map(s=>sectorCard(s,ctx)).join(''):`<div class="panel"><div class="empty">لا توجد جهات بعد. <button class="btn primary" onclick="showSectorEditor()">إضافة جهة</button></div></div>`}</div>
  <div class="split">
    <section class="panel"><div class="panel-head"><h3>القضايا المفتوحة</h3><span class="chip red">${open.length}</span></div><div class="table-wrap">${caseTable(rows,ctx)}</div></section>
    <section class="panel"><div class="panel-head"><h3>أقرب المواعيد</h3></div><div class="panel-body cards-list">${[...upcomingSessions.slice(0,4).map(s=>({type:'جلسة',at:s.dateTime||s.date,caseId:s.caseId,text:s.summary||s.result||'جلسة قادمة'})),...upcomingRem.slice(0,4).map(r=>({type:'تذكير',at:r.at,caseId:r.caseId,text:r.title}))].sort((a,b)=>new Date(a.at)-new Date(b.at)).slice(0,7).map(x=>`<div class="item-card"><div class="item-card-head"><div><h4>${esc(x.type)} • ${fmtDateTime(x.at)}</h4><p>${esc(x.text)}</p></div><button class="btn small" onclick="openCase('${x.caseId}')">فتح</button></div></div>`).join('')||'<div class="empty">لا توجد مواعيد قادمة</div>'}</div></section>
  </div>`;
}
function stat(label,value,hint,kind=''){return `<div class="stat"><div class="label">${esc(label)}</div><div class="value">${value}</div><div class="hint ${kind==='red'?'': ''}">${esc(hint||'')}</div></div>`;}
function sectorCard(s,ctx){ const cc=ctx.cases.filter(c=>c.sectorId===s.id), o=cc.filter(c=>c.status==='open').length, cl=cc.filter(c=>c.status==='closed').length; return `<div class="sector-card" onclick="openSector('${s.id}')"><h3>${esc(s.name)}</h3><div class="sector-meta"><span class="chip">الإجمالي ${cc.length}</span><span class="chip red">مفتوح ${o}</span><span class="chip green">منتهي ${cl}</span></div></div>`;}
function caseTable(rows,ctx){ if(!rows.length)return '<div class="empty">لا توجد قضايا</div>'; return `<table class="table"><thead><tr><th>الحالة</th><th>رقم القضية</th><th>الموضوع</th><th>القطاع</th><th>آخر خطوة</th><th>الجلسة القادمة</th><th></th></tr></thead><tbody>${rows.map(c=>`<tr><td><span class="status-dot ${c.status==='closed'?'status-closed':'status-open'}"></span>${statusText(c.status)}</td><td><a class="link" onclick="openCase('${c.id}')">${esc(c.caseNumber)}</a></td><td>${esc(c.subject)}</td><td>${esc(sectorName(c.sectorId,ctx))}</td><td>${esc(c.last?.label||'—')}<br><small class="muted">${c.last?fmtDate(c.last.date):''}</small></td><td>${c.ns?fmtDateTime(c.ns.dateTime||c.ns.date):'—'}</td><td><button class="btn small" onclick="openCase('${c.id}')">فتح</button></td></tr>`).join('')}</tbody></table>`;}

async function renderSector(ctx){
 const s=ctx.sectors.find(x=>x.id===appState.sectorId); if(!s){appState.view='dashboard';return renderDashboard(ctx);} const cs=ctx.cases.filter(c=>c.sectorId===s.id); const rows=[]; for(const c of cs){rows.push({...c,last:await lastStepForCase(c.id,ctx),ns:nextSession(c.id,ctx)});} return `<div class="page-head"><div><button class="btn small" onclick="goDashboard()">← الرئيسية</button><h2 style="margin-top:10px">${esc(s.name)}</h2><p>${cs.length} قضية داخل القطاع</p></div><div class="row"><button class="btn" onclick="showSectorEditor()">تعديل الجهات</button><button class="btn primary" onclick="showCaseForm(null,'${s.id}')">＋ قضية جديدة</button></div></div><section class="panel"><div class="panel-head"><h3>القضايا</h3><div class="row"><span class="chip red">مفتوحة ${cs.filter(x=>x.status==='open').length}</span><span class="chip green">منتهية ${cs.filter(x=>x.status==='closed').length}</span></div></div><div class="table-wrap">${caseTable(rows,ctx)}</div></section>`;
}

async function renderSearch(ctx){
 const q=normalize(appState.search); const partyMap=new Map(), attMap=new Map();
 for(const p of ctx.parties){if(normalize(p.name).includes(q)||normalize(p.role).includes(q)){partyMap.set(p.caseId,true);}}
 for(const a of ctx.attachments){if(normalize(a.label).includes(q)||normalize(a.originalName).includes(q)||normalize(a.category).includes(q)){attMap.set(a.caseId,true);}}
 const hits=ctx.cases.filter(c=>[c.caseNumber,c.subject,c.authority,c.year,sectorName(c.sectorId,ctx),caseTypeName(c.caseTypeId,ctx)].some(v=>normalize(v).includes(q))||partyMap.has(c.id)||attMap.has(c.id));
 const rows=[]; for(const c of hits) rows.push({...c,last:await lastStepForCase(c.id,ctx),ns:nextSession(c.id,ctx)});
 return `<div class="page-head"><div><h2>نتائج البحث</h2><p>البحث عن: ${esc(appState.search)} • ${hits.length} نتيجة</p></div><button class="btn" onclick="clearSearch()">مسح البحث</button></div><section class="panel"><div class="table-wrap">${caseTable(rows,ctx)}</div></section>`;
}
window.clearSearch=()=>{appState.search='';render();};

async function renderCase(ctx){
 const c=ctx.cases.find(x=>x.id===appState.caseId); if(!c){return `<div class="empty">القضية غير موجودة <button class="btn" onclick="goDashboard()">الرئيسية</button></div>`;}
 const ro=c.status==='closed'; const last=await lastStepForCase(c.id,ctx); const ns=nextSession(c.id,ctx); const tabs=[['overview','الملخص'],['parties','الأطراف'],['sessions','الجلسات'],['actions','الإجراءات'],['attachments','المرفقات'],['reminders','التذكيرات'],['timeline','السجل الزمني']];
 let body=''; if(appState.tab==='parties')body=tabParties(c,ctx,ro); else if(appState.tab==='sessions')body=tabSessions(c,ctx,ro); else if(appState.tab==='actions')body=tabActions(c,ctx,ro); else if(appState.tab==='attachments')body=tabAttachments(c,ctx,ro); else if(appState.tab==='reminders')body=tabReminders(c,ctx,ro); else if(appState.tab==='timeline')body=tabTimeline(c,ctx); else body=tabOverview(c,ctx,last,ns,ro);
 return `<button class="btn small" onclick="${c.sectorId?`openSector('${c.sectorId}')`:'goDashboard()'}">← رجوع</button>
 <div class="case-hero"><div><h2>قضية ${esc(c.caseNumber)}</h2><div class="meta"><span class="chip ${c.status==='closed'?'green':'red'}"><span class="status-dot ${c.status==='closed'?'status-closed':'status-open'}"></span>${statusText(c.status)}</span><span class="chip">${esc(sectorName(c.sectorId,ctx))}</span><span class="chip">${esc(caseTypeName(c.caseTypeId,ctx))}</span>${ro?'<span class="chip orange">قراءة فقط</span>':''}</div><p class="muted">${esc(c.subject)}</p></div><div class="row">${ro?`<button class="btn warn" onclick="reopenCase('${c.id}')">إعادة فتح القضية</button>`:`<button class="btn" onclick="showCaseForm('${c.id}')">تعديل البيانات</button><button class="btn success" onclick="closeCase('${c.id}')">إنهاء القضية</button>`}<button class="btn" onclick="printCaseReport('${c.id}')">تقرير PDF</button><button class="btn primary" onclick="exportCasePack('${c.id}')">ملف القضية الكامل</button></div></div>
 <div class="tabs">${tabs.map(([k,l])=>`<button class="tab ${appState.tab===k?'active':''}" data-tab="${k}">${l}</button>`).join('')}</div>${body}`;
}
function tabOverview(c,ctx,last,ns,ro){ const ps=ctx.parties.filter(x=>x.caseId===c.id); return `<div class="detail-grid">
 ${field('رقم القضية',c.caseNumber)}${field('سنة القضية',c.year)}${field('القطاع / الجهة',sectorName(c.sectorId,ctx))}${field('الجهة المختصة',c.authority||'—')}${field('نوع القضية',caseTypeName(c.caseTypeId,ctx))}${field('تاريخ الورود',fmtDate(c.receivedDate))}${field('الموضوع',c.subject)}${field('الأطراف',ps.map(x=>`${x.name} (${x.role})`).join('، ')||'—')}${field('آخر خطوة',last?`${last.label} — ${fmtDate(last.date)}`:'—')}${field('الجلسة القادمة',ns?fmtDateTime(ns.dateTime||ns.date):'—')}${field('الملاحظات',c.notes||'—')}
 </div>`; }
function field(l,v){return `<div class="field-card"><label>${esc(l)}</label><div>${esc(v)}</div></div>`;}
function tabParties(c,ctx,ro){ const arr=ctx.parties.filter(x=>x.caseId===c.id); return `<section class="panel"><div class="panel-head"><h3>أطراف القضية</h3>${ro?'':`<button class="btn primary" onclick="showPartyForm('${c.id}')">＋ إضافة طرف</button>`}</div><div class="panel-body cards-list">${arr.map(p=>`<div class="item-card"><div class="item-card-head"><div><h4>${esc(p.name)}</h4><p>${esc(p.role)}</p></div>${ro?'':`<div><button class="btn small" onclick="showPartyForm('${c.id}','${p.id}')">تعديل</button> <button class="btn small danger" onclick="deleteEntity('parties','${p.id}')">حذف</button></div>`}</div></div>`).join('')||'<div class="empty">لا توجد أطراف</div>'}</div></section>`;}
function tabSessions(c,ctx,ro){ const arr=ctx.sessions.filter(x=>x.caseId===c.id).sort((a,b)=>new Date(b.dateTime||b.date)-new Date(a.dateTime||a.date)); return `<section class="panel"><div class="panel-head"><h3>الجلسات</h3>${ro?'':`<button class="btn primary" onclick="showSessionForm('${c.id}')">＋ جلسة</button>`}</div><div class="panel-body cards-list">${arr.map(s=>{const files=ctx.attachments.filter(a=>a.parentType==='session'&&a.parentId===s.id);return `<div class="item-card"><div class="item-card-head"><div><h4>${fmtDateTime(s.dateTime||s.date)}</h4><p>${esc(s.summary||'')}</p>${s.result?`<p><b>القرار/النتيجة:</b> ${esc(s.result)}</p>`:''}${s.nextDate?`<p><b>الجلسة التالية:</b> ${fmtDateTime(s.nextDate)}</p>`:''}<small class="muted">${files.length} مرفق</small></div><div class="row"><button class="btn small" onclick="previewRecord('session','${s.id}')">معاينة</button>${ro?'':`<button class="btn small warn" onclick="remindForSession('${s.id}')">تذكير</button><button class="btn small" onclick="showSessionForm('${c.id}','${s.id}')">تعديل</button><button class="btn small danger" onclick="deleteEntity('sessions','${s.id}')">حذف</button>`}</div></div></div>`}).join('')||'<div class="empty">لا توجد جلسات</div>'}</div></section>`;}
function tabActions(c,ctx,ro){ const arr=ctx.actions.filter(x=>x.caseId===c.id).sort((a,b)=>new Date(b.date)-new Date(a.date)); return `<section class="panel"><div class="panel-head"><h3>الإجراءات</h3>${ro?'':`<div class="row"><button class="btn" onclick="showActionTypeEditor()">أنواع الإجراءات</button><button class="btn primary" onclick="showActionForm('${c.id}')">＋ إجراء</button></div>`}</div><div class="panel-body cards-list">${arr.map(a=>{const files=ctx.attachments.filter(x=>x.parentType==='action'&&x.parentId===a.id);return `<div class="item-card"><div class="item-card-head"><div><h4>${esc(a.typeName||'إجراء')} • ${fmtDate(a.date)}</h4><p>${esc(a.summary||'')}</p><small class="muted">${files.length} مرفق</small></div><div class="row"><button class="btn small" onclick="previewRecord('action','${a.id}')">معاينة</button>${ro?'':`<button class="btn small" onclick="showActionForm('${c.id}','${a.id}')">تعديل</button><button class="btn small danger" onclick="deleteEntity('actions','${a.id}')">حذف</button>`}</div></div></div>`}).join('')||'<div class="empty">لا توجد إجراءات</div>'}</div></section>`;}
function tabAttachments(c,ctx,ro){ const arr=ctx.attachments.filter(x=>x.caseId===c.id&&x.parentType==='case'); return `<section class="panel"><div class="panel-head"><h3>مرفقات القضية</h3>${ro?'':`<button class="btn primary" onclick="showAttachmentForm('${c.id}','case','${c.id}')">＋ إرفاق ملفات</button>`}</div><div>${fileRows(arr,ro)}</div></section>`;}
function fileRows(arr,ro=false){ return arr.length?arr.map(a=>`<div class="file-row"><div class="file-meta"><strong>${esc(a.label||a.originalName)}</strong><small>${esc(a.originalName)} • ${bytesFmt(a.size)} • ${fmtDate(a.fileDate||a.createdAt)}${a.category?' • '+esc(a.category):''}</small></div><div class="file-actions"><button class="btn small" onclick="previewAttachment('${a.id}')">معاينة</button><button class="btn small" onclick="exportAttachment('${a.id}')">تصدير</button>${ro?'':`<button class="btn small" onclick="editAttachmentMeta('${a.id}')">تعديل</button><button class="btn small danger" onclick="deleteAttachment('${a.id}')">حذف</button>`}</div></div>`).join(''):'<div class="empty">لا توجد مرفقات</div>'; }
function tabReminders(c,ctx,ro){ const arr=ctx.reminders.filter(x=>x.caseId===c.id).sort((a,b)=>new Date(a.at)-new Date(b.at)); return `<section class="panel"><div class="panel-head"><h3>التذكيرات</h3>${ro?'':`<button class="btn primary" onclick="showReminderForm('${c.id}')">＋ تذكير</button>`}</div><div class="panel-body cards-list">${arr.map(r=>`<div class="item-card ${!r.done&&new Date(r.at)<=new Date()?'reminder-due':''}"><div class="item-card-head"><div><h4>${r.done?'✅':'🔔'} ${esc(r.title)}</h4><p>${fmtDateTime(r.at)}${r.note?' — '+esc(r.note):''}</p><small class="muted">${r.done?'تم':'قيد المتابعة'}${appState.desktop&&r.scheduledDesktop?' • مجدول في Windows':''}</small></div><div class="row"><button class="btn small" onclick="downloadReminderICS('${r.id}')">إضافة للتقويم</button>${ro?'':`<button class="btn small success" onclick="toggleReminder('${r.id}')">${r.done?'إعادة فتح':'تم'}</button><button class="btn small" onclick="showReminderForm('${c.id}','${r.id}')">تعديل</button><button class="btn small danger" onclick="deleteReminder('${r.id}')">حذف</button>`}</div></div></div>`).join('')||'<div class="empty">لا توجد تذكيرات</div>'}</div></section>`;}
function tabTimeline(c,ctx){ const arr=[]; for(const t of ctx.timeline.filter(x=>x.caseId===c.id))arr.push({at:t.at,title:t.title,detail:t.detail}); for(const a of ctx.actions.filter(x=>x.caseId===c.id))arr.push({at:a.date||a.createdAt,title:`إجراء: ${a.typeName}`,detail:a.summary}); for(const s of ctx.sessions.filter(x=>x.caseId===c.id))arr.push({at:s.dateTime||s.date,title:'جلسة',detail:s.summary||s.result}); arr.sort((a,b)=>new Date(b.at)-new Date(a.at)); return `<section class="panel"><div class="panel-head"><h3>السجل الزمني</h3></div><div class="panel-body"><div class="timeline">${arr.map(x=>`<div class="timeline-item"><h4>${esc(x.title||'تحديث')}</h4><p>${esc(x.detail||'')}</p><small>${fmtDateTime(x.at)}</small></div>`).join('')||'<div class="empty">لا يوجد سجل بعد</div>'}</div></div></section>`;}

function modal(title,body,foot='',wide=false){ const wrap=document.createElement('div'); wrap.className='modal-backdrop'; wrap.innerHTML=`<div class="modal ${wide?'wide':''}"><div class="modal-head"><h3>${esc(title)}</h3><button class="btn small" data-close>✕</button></div><div class="modal-body">${body}</div>${foot?`<div class="modal-foot">${foot}</div>`:''}</div>`; document.body.appendChild(wrap); wrap.addEventListener('click',e=>{if(e.target===wrap||e.target.closest('[data-close]'))wrap.remove();}); return wrap; }
function closeModal(el){ el.closest('.modal-backdrop')?.remove(); }

window.showSettings=()=>modal('الإعدادات',`<div class="cards-list"><div class="item-card"><h4>الجهات / القطاعات</h4><p>إضافة وتعديل وترتيب الجهات التي تظهر في الواجهة الرئيسية.</p><button class="btn" onclick="this.closest('.modal-backdrop').remove();showSectorEditor()">تعديل الجهات</button></div><div class="item-card"><h4>أنواع القضايا</h4><p>قائمة قابلة للزيادة والتعديل.</p><button class="btn" onclick="this.closest('.modal-backdrop').remove();showCaseTypeEditor()">تعديل أنواع القضايا</button></div><div class="item-card"><h4>أنواع الإجراءات</h4><p>مخاطبة، تصرف نيابة، إرسال... مع إمكانية التعديل.</p><button class="btn" onclick="this.closest('.modal-backdrop').remove();showActionTypeEditor()">تعديل أنواع الإجراءات</button></div><div class="item-card"><h4>الإشعارات</h4><p>على نسخة Windows يتم جدولة التذكيرات في النظام بدون إبقاء البرنامج مفتوحًا. على iPhone استخدم «إضافة للتقويم» للحصول على تنبيه موثوق عند إغلاق الـPWA.</p><button class="btn" onclick="requestNotifyPermission()">تفعيل إشعارات البرنامج</button></div></div>`);

async function genericListEditor(store,title){ const items=await getAll(store); const body=`<div id="list-editor" class="list-editor">${items.map(x=>listRow(x)).join('')}</div><hr style="border:0;border-top:1px solid #22334b;margin:14px 0"><div class="inline-add"><input id="new-list-name" class="input" placeholder="اسم جديد"><button class="btn primary" id="add-list">إضافة</button></div>`; const m=modal(title,body,'<button class="btn" data-close>إغلاق</button>'); function listRow(x){return `<div class="list-edit-row" data-id="${x.id}"><input class="input" value="${esc(x.name)}"><button class="btn small" data-save>حفظ</button><button class="btn small danger" data-del>حذف</button></div>`;} $('#add-list',m).onclick=async()=>{const name=$('#new-list-name',m).value.trim();if(!name)return;const x=await saveEntity(store,{name});$('#list-editor',m).insertAdjacentHTML('beforeend',listRow(x));$('#new-list-name',m).value='';bind();render();}; function bind(){ $$('[data-save]',m).forEach(b=>b.onclick=async()=>{const r=b.closest('[data-id]');const x=await getOne(store,r.dataset.id);x.name=$('input',r).value.trim();await saveEntity(store,x);toast('تم الحفظ','success');render();}); $$('[data-del]',m).forEach(b=>b.onclick=async()=>{const r=b.closest('[data-id]'); const id=r.dataset.id; let used=false; if(store==='sectors')used=(await getAll('cases')).some(x=>x.sectorId===id); if(store==='caseTypes')used=(await getAll('cases')).some(x=>x.caseTypeId===id); if(store==='actionTypes')used=(await getAll('actions')).some(x=>x.typeId===id); if(used){toast('لا يمكن حذف العنصر لأنه مستخدم في بيانات مسجلة. يمكنك تعديل اسمه بدلًا من الحذف.','error');return;} if(!confirm('حذف هذا العنصر من القائمة؟'))return; await del(store,id);r.remove();render();});} bind(); }
window.showSectorEditor=()=>genericListEditor('sectors','تعديل الجهات / القطاعات');
window.showCaseTypeEditor=()=>genericListEditor('caseTypes','أنواع القضايا');
window.showActionTypeEditor=()=>genericListEditor('actionTypes','أنواع الإجراءات');

window.showCaseForm=async function(caseId=null,sectorId=null){ const ctx=await getContext(); const c=caseId?ctx.cases.find(x=>x.id===caseId):null; const b=`<div class="form-grid"><div class="form-group"><label>رقم القضية *</label><input id="f-number" class="input" value="${esc(c?.caseNumber||'')}"></div><div class="form-group"><label>سنة القضية</label><input id="f-year" class="input" type="number" value="${esc(c?.year||new Date().getFullYear())}"></div><div class="form-group"><label>القطاع / الجهة *</label><select id="f-sector" class="select"><option value="">اختر</option>${ctx.sectors.map(s=>`<option value="${s.id}" ${(c?.sectorId||sectorId)===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select></div><div class="form-group"><label>الجهة المختصة</label><input id="f-authority" class="input" value="${esc(c?.authority||'')}"></div><div class="form-group"><label>نوع القضية</label><select id="f-type" class="select"><option value="">—</option>${ctx.caseTypes.map(t=>`<option value="${t.id}" ${c?.caseTypeId===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select></div><div class="form-group"><label>تاريخ الورود</label><input id="f-received" class="input" type="date" value="${esc(c?.receivedDate||new Date().toISOString().slice(0,10))}"></div><div class="form-group full"><label>موضوع القضية *</label><textarea id="f-subject" class="textarea">${esc(c?.subject||'')}</textarea></div><div class="form-group full"><label>ملاحظات</label><textarea id="f-notes" class="textarea">${esc(c?.notes||'')}</textarea></div></div>`; const m=modal(c?'تعديل القضية':'قضية جديدة',b,`<button class="btn primary" id="save-case">حفظ</button><button class="btn" data-close>إلغاء</button>`); $('#save-case',m).onclick=async()=>{const num=$('#f-number',m).value.trim(), subject=$('#f-subject',m).value.trim(), sid=$('#f-sector',m).value;if(!num||!subject||!sid){toast('رقم القضية والموضوع والقطاع حقول مطلوبة','error');return;}const dup=(await getAll('cases')).find(x=>x.caseNumber===num&&x.id!==caseId);if(dup){toast('رقم القضية مستخدم بالفعل ولا يمكن تكراره','error');return;}const obj=c||{id:uid(),status:'open'};Object.assign(obj,{caseNumber:num,year:$('#f-year',m).value,sectorId:sid,authority:$('#f-authority',m).value.trim(),caseTypeId:$('#f-type',m).value,receivedDate:$('#f-received',m).value,subject,notes:$('#f-notes',m).value.trim()});await saveEntity('cases',obj);await addTimeline(obj.id,c?'تعديل بيانات القضية':'إنشاء القضية',subject);m.remove();openCase(obj.id);};};

async function addTimeline(caseId,title,detail=''){await saveEntity('timeline',{caseId,title,detail,at:nowISO()},{audit:false});}
window.closeCase=async id=>{if(!confirm('إنهاء القضية وتحويلها إلى قراءة فقط؟'))return;const c=await getOne('cases',id);c.status='closed';c.closedAt=nowISO();await saveEntity('cases',c);await addTimeline(id,'إنهاء القضية','تم تحويل القضية إلى منتهية وقراءة فقط');toast('تم إنهاء القضية','success');render();};
window.reopenCase=async id=>{if(!confirm('إعادة فتح القضية والسماح بالتعديل؟'))return;const c=await getOne('cases',id);c.status='open';c.reopenedAt=nowISO();await saveEntity('cases',c);await addTimeline(id,'إعادة فتح القضية','تم إعادة فتح القضية');toast('تم إعادة فتح القضية','success');render();};

window.showPartyForm=async function(caseId,id=null){const p=id?await getOne('parties',id):null;const m=modal(p?'تعديل طرف':'إضافة طرف',`<div class="form-grid"><div class="form-group"><label>الاسم *</label><input id="p-name" class="input" value="${esc(p?.name||'')}"></div><div class="form-group"><label>الصفة *</label><input id="p-role" class="input" value="${esc(p?.role||'')}"></div></div>`,`<button id="p-save" class="btn primary">حفظ</button><button class="btn" data-close>إلغاء</button>`);$('#p-save',m).onclick=async()=>{const name=$('#p-name',m).value.trim(),role=$('#p-role',m).value.trim();if(!name||!role)return toast('الاسم والصفة مطلوبان','error');const o=p||{id:uid(),caseId};Object.assign(o,{name,role});await saveEntity('parties',o);await addTimeline(caseId,p?'تعديل طرف':'إضافة طرف',`${name} — ${role}`);m.remove();render();};};

window.showSessionForm=async function(caseId,id=null){const s=id?await getOne('sessions',id):null; const b=`<div class="form-grid"><div class="form-group"><label>تاريخ ووقت الجلسة *</label><input id="s-date" class="input" type="datetime-local" value="${s?.dateTime?localDateInputValue(new Date(s.dateTime)):localDateInputValue()}"></div><div class="form-group"><label>الجلسة التالية</label><input id="s-next" class="input" type="datetime-local" value="${s?.nextDate?localDateInputValue(new Date(s.nextDate)):''}"></div><div class="form-group full"><label>ملخص الجلسة</label><textarea id="s-summary" class="textarea">${esc(s?.summary||'')}</textarea></div><div class="form-group full"><label>القرار / النتيجة</label><textarea id="s-result" class="textarea">${esc(s?.result||'')}</textarea></div><div class="form-group full"><label>ملاحظات</label><textarea id="s-notes" class="textarea">${esc(s?.notes||'')}</textarea></div></div>${s?`<div style="margin-top:14px"><button class="btn" onclick="showAttachmentForm('${caseId}','session','${s.id}')">＋ إضافة مرفقات للجلسة</button></div>`:'<p class="muted">احفظ الجلسة أولًا ثم يمكنك إضافة مرفقات لها من المعاينة.</p>'}`; const m=modal(s?'تعديل جلسة':'إضافة جلسة',b,`<button class="btn primary" id="s-save">حفظ</button><button class="btn" data-close>إلغاء</button>`);$('#s-save',m).onclick=async()=>{const v=$('#s-date',m).value;if(!v)return toast('تاريخ الجلسة مطلوب','error');const o=s||{id:uid(),caseId};Object.assign(o,{dateTime:new Date(v).toISOString(),nextDate:$('#s-next',m).value?new Date($('#s-next',m).value).toISOString():'',summary:$('#s-summary',m).value.trim(),result:$('#s-result',m).value.trim(),notes:$('#s-notes',m).value.trim()});await saveEntity('sessions',o);await addTimeline(caseId,s?'تعديل جلسة':'إضافة جلسة',`${fmtDateTime(o.dateTime)} — ${o.summary||o.result||''}`);m.remove();render();};};

window.showActionForm=async function(caseId,id=null){const ctx=await getContext(), a=id?ctx.actions.find(x=>x.id===id):null;const b=`<div class="form-grid"><div class="form-group"><label>نوع الإجراء *</label><select id="a-type" class="select">${ctx.actionTypes.map(t=>`<option value="${t.id}" data-name="${esc(t.name)}" ${a?.typeId===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select></div><div class="form-group"><label>تاريخ الإجراء *</label><input id="a-date" class="input" type="date" value="${esc(a?.date||new Date().toISOString().slice(0,10))}"></div><div class="form-group full"><label>ملخص / تفاصيل الإجراء</label><textarea id="a-summary" class="textarea">${esc(a?.summary||'')}</textarea></div></div>${a?`<div style="margin-top:14px"><button class="btn" onclick="showAttachmentForm('${caseId}','action','${a.id}')">＋ إضافة مرفقات للإجراء</button></div>`:'<p class="muted">احفظ الإجراء أولًا ثم أضف مرفقاته من المعاينة.</p>'}`;const m=modal(a?'تعديل إجراء':'إضافة إجراء',b,`<button class="btn primary" id="a-save">حفظ</button><button class="btn" data-close>إلغاء</button>`);$('#a-save',m).onclick=async()=>{const sel=$('#a-type',m), opt=sel.selectedOptions[0],date=$('#a-date',m).value;if(!sel.value||!date)return toast('نوع وتاريخ الإجراء مطلوبان','error');const o=a||{id:uid(),caseId};Object.assign(o,{typeId:sel.value,typeName:opt.textContent,date,summary:$('#a-summary',m).value.trim()});await saveEntity('actions',o);await addTimeline(caseId,a?'تعديل إجراء':`إجراء: ${o.typeName}`,o.summary);m.remove();render();};};

window.previewRecord=async function(type,id){const ctx=await getContext();const obj=type==='session'?ctx.sessions.find(x=>x.id===id):ctx.actions.find(x=>x.id===id);if(!obj)return;const files=ctx.attachments.filter(a=>a.parentType===type&&a.parentId===id);const title=type==='session'?`جلسة ${fmtDateTime(obj.dateTime||obj.date)}`:`${obj.typeName||'إجراء'} — ${fmtDate(obj.date)}`;const text=type==='session'?`<div class="detail-grid">${field('ملخص الجلسة',obj.summary||'—')}${field('القرار / النتيجة',obj.result||'—')}${field('الجلسة التالية',obj.nextDate?fmtDateTime(obj.nextDate):'—')}${field('ملاحظات',obj.notes||'—')}</div>`:`<div class="detail-grid">${field('النوع',obj.typeName||'—')}${field('التاريخ',fmtDate(obj.date))}${field('التفاصيل',obj.summary||'—')}</div>`;modal(title,`${text}<div style="margin-top:14px" class="panel"><div class="panel-head"><h3>المرفقات</h3><button class="btn small primary" onclick="showAttachmentForm('${obj.caseId}','${type}','${obj.id}')">＋ إضافة</button></div>${fileRows(files,false)}</div>`,'<button class="btn" data-close>إغلاق</button>',true);};

window.showAttachmentForm=async function(caseId,parentType='case',parentId=caseId){const b=`<div class="form-grid"><div class="form-group full"><label>اختيار ملفات (يمكن اختيار أكثر من ملف)</label><input id="att-files" class="input" type="file" multiple accept=".pdf,.doc,.docx,image/*"></div><div class="form-group"><label>اسم / بادئة المرفق</label><input id="att-label" class="input" placeholder="مثال: مخاطبة"></div><div class="form-group"><label>التصنيف</label><input id="att-cat" class="input" placeholder="مثال: محضر / مخاطبات"></div><div class="form-group"><label>تاريخ المستند</label><input id="att-date" class="input" type="date" value="${new Date().toISOString().slice(0,10)}"></div><div class="form-group full"><label>ملاحظات</label><textarea id="att-note" class="textarea"></textarea></div></div>`;const m=modal('إضافة مرفقات',b,`<button class="btn primary" id="att-save">تشفير وحفظ</button><button class="btn" data-close>إلغاء</button>`);$('#att-save',m).onclick=async()=>{const files=Array.from($('#att-files',m).files||[]);if(!files.length)return toast('اختر ملفًا واحدًا على الأقل','error');const prefix=$('#att-label',m).value.trim(),cat=$('#att-cat',m).value.trim(),date=$('#att-date',m).value,note=$('#att-note',m).value.trim();let i=0;for(const f of files){i++;const ab=await f.arrayBuffer(),hash=await sha256(ab);const existing=(await getAll('attachments')).find(a=>a.hash===hash&&a.caseId===caseId);if(existing){toast(`الملف ${f.name} موجود بالفعل`);continue;}const enc=await encryptBuffer(ab);const label=prefix?(files.length>1?`${prefix} ${i}`:prefix):f.name;await saveEntity('attachments',{id:uid(),caseId,parentType,parentId,label,category:cat,fileDate:date,note,originalName:f.name,mime:f.type||mimeFromName(f.name),size:f.size,hash,iv:enc.iv,data:enc.data},{audit:false});await addTimeline(caseId,'إضافة مرفق',label);}m.remove();toast('تم حفظ وتشفير المرفقات','success');render();};};
function mimeFromName(n){const e=n.split('.').pop().toLowerCase();return e==='pdf'?'application/pdf':e==='docx'?'application/vnd.openxmlformats-officedocument.wordprocessingml.document':e==='doc'?'application/msword':e==='png'?'image/png':['jpg','jpeg'].includes(e)?'image/jpeg':'application/octet-stream';}
window.editAttachmentMeta=async id=>{const a=await getOne('attachments',id);if(!a)return;const m=modal('تعديل بيانات المرفق',`<div class="form-grid"><div class="form-group"><label>اسم المرفق</label><input id="em-label" class="input" value="${esc(a.label)}"></div><div class="form-group"><label>التصنيف</label><input id="em-cat" class="input" value="${esc(a.category||'')}"></div><div class="form-group"><label>التاريخ</label><input id="em-date" type="date" class="input" value="${esc(a.fileDate||'')}"></div><div class="form-group full"><label>ملاحظات</label><textarea id="em-note" class="textarea">${esc(a.note||'')}</textarea></div></div>`,`<button id="em-save" class="btn primary">حفظ</button><button class="btn" data-close>إلغاء</button>`);$('#em-save',m).onclick=async()=>{a.label=$('#em-label',m).value.trim()||a.originalName;a.category=$('#em-cat',m).value.trim();a.fileDate=$('#em-date',m).value;a.note=$('#em-note',m).value.trim();await saveEntity('attachments',a,{audit:false});m.remove();render();};};
window.deleteAttachment=async id=>{if(!confirm('حذف المرفق؟'))return;await del('attachments',id);toast('تم حذف المرفق');render();};
window.exportAttachment=async id=>{const a=await getOne('attachments',id);if(!a)return;try{const ab=await decryptAttachment(a);downloadBlob(new Blob([ab],{type:a.mime}),a.originalName); }catch(e){toast('تعذر فك تشفير الملف','error');}};
window.previewAttachment=async id=>{const a=await getOne('attachments',id);if(!a)return;try{const ab=await decryptAttachment(a);if(a.mime.startsWith('image/')||a.mime==='application/pdf'){const u=URL.createObjectURL(new Blob([ab],{type:a.mime}));const content=a.mime==='application/pdf'?`<iframe src="${u}"></iframe>`:`<img src="${u}" alt="${esc(a.label)}">`;const m=modal(`معاينة: ${a.label}`,`<div class="preview">${content}</div>`,`<button class="btn" onclick="exportAttachment('${a.id}')">تصدير</button><button class="btn" data-close>إغلاق</button>`,true);m.addEventListener('DOMNodeRemoved',()=>URL.revokeObjectURL(u),{once:true});}else if(a.originalName.toLowerCase().endsWith('.docx')){const txt=await extractDocxText(ab);modal(`معاينة نصية: ${a.label}`,`<div class="preview"><div class="preview-text">${esc(txt||'تعذر استخراج النص من المستند.')}</div></div>`,`<button class="btn" onclick="exportAttachment('${a.id}')">فتح / تصدير الملف الأصلي</button><button class="btn" data-close>إغلاق</button>`,true);}else{modal(`المرفق: ${a.label}`,`<div class="empty">المعاينة الداخلية غير متاحة لهذا النوع. يمكنك تصدير الملف وفتحه ببرنامج Word أو البرنامج المناسب.</div>`,`<button class="btn primary" onclick="exportAttachment('${a.id}')">تصدير الملف</button><button class="btn" data-close>إغلاق</button>`);} }catch(e){console.error(e);toast('تعذر معاينة الملف','error');}};

async function extractDocxText(buffer){const b=new Uint8Array(buffer),dv=new DataView(buffer);let eocd=-1;for(let i=b.length-22;i>=Math.max(0,b.length-66000);i--){if(dv.getUint32(i,true)===0x06054b50){eocd=i;break;}}if(eocd<0)throw new Error('zip');const cdOff=dv.getUint32(eocd+16,true), entries=dv.getUint16(eocd+10,true);let p=cdOff,target=null;const dec=new TextDecoder();for(let i=0;i<entries;i++){if(dv.getUint32(p,true)!==0x02014b50)break;const method=dv.getUint16(p+10,true),cs=dv.getUint32(p+20,true),fnl=dv.getUint16(p+28,true),exl=dv.getUint16(p+30,true),col=dv.getUint16(p+32,true),lo=dv.getUint32(p+42,true),name=dec.decode(b.slice(p+46,p+46+fnl));if(name==='word/document.xml'){target={method,cs,lo};break;}p+=46+fnl+exl+col;}if(!target)throw new Error('doc');const lp=target.lo,lf=dv.getUint16(lp+26,true),le=dv.getUint16(lp+28,true),start=lp+30+lf+le,comp=b.slice(start,start+target.cs);let raw;if(target.method===0)raw=comp;else if(target.method===8){const ds=new DecompressionStream('deflate-raw');raw=new Uint8Array(await new Response(new Blob([comp]).stream().pipeThrough(ds)).arrayBuffer());}else throw new Error('method');const xml=dec.decode(raw).replace(/<w:tab\s*\/>/g,'\t').replace(/<\/w:p>/g,'\n').replace(/<[^>]+>/g,'');const ta=document.createElement('textarea');ta.innerHTML=xml;return ta.value.replace(/\n{3,}/g,'\n\n').trim();}

window.showReminderForm=async function(caseId,id=null,presetTitle='',presetAt=''){const r=id?await getOne('reminders',id):null;const b=`<div class="form-grid"><div class="form-group full"><label>عنوان التذكير *</label><input id="r-title" class="input" value="${esc(r?.title||presetTitle||'')}"></div><div class="form-group"><label>التاريخ والوقت *</label><input id="r-at" class="input" type="datetime-local" value="${r?.at?localDateInputValue(new Date(r.at)):presetAt?localDateInputValue(new Date(presetAt)):localDateInputValue(new Date(Date.now()+86400000))}"></div><div class="form-group"><label>نوع التذكير</label><select id="r-kind" class="select"><option ${r?.kind==='جلسة'?'selected':''}>جلسة</option><option ${r?.kind==='متابعة'?'selected':''}>متابعة</option><option ${r?.kind==='إجراء'?'selected':''}>إجراء</option><option ${r?.kind==='عام'?'selected':''}>عام</option></select></div><div class="form-group full"><label>ملاحظة</label><textarea id="r-note" class="textarea">${esc(r?.note||'')}</textarea></div></div><p class="muted">نسخة Windows تجدول التنبيه في Windows حتى لو أغلقت البرنامج. على iPhone استخدم زر «إضافة للتقويم» بعد الحفظ للحصول على تنبيه عند إغلاق الـPWA.</p>`;const m=modal(r?'تعديل تذكير':'إضافة تذكير',b,`<button class="btn primary" id="r-save">حفظ التذكير</button><button class="btn" data-close>إلغاء</button>`);$('#r-save',m).onclick=async()=>{const title=$('#r-title',m).value.trim(),v=$('#r-at',m).value;if(!title||!v)return toast('العنوان والموعد مطلوبان','error');const o=r||{id:uid(),caseId,done:false};Object.assign(o,{title,at:new Date(v).toISOString(),kind:$('#r-kind',m).value,note:$('#r-note',m).value.trim(),firedAt:null});await saveEntity('reminders',o);if(appState.desktop) o.scheduledDesktop=await scheduleDesktopReminder(o);await put('reminders',o);await addTimeline(caseId,r?'تعديل تذكير':'إضافة تذكير',`${title} — ${fmtDateTime(o.at)}`);m.remove();toast('تم حفظ التذكير','success');render();};};
window.remindForSession=async function(sessionId){const s=await getOne('sessions',sessionId);if(!s)return;const c=await getOne('cases',s.caseId);showReminderForm(s.caseId,null,`جلسة قضية ${c?.caseNumber||''}`,s.dateTime||s.date);};
async function scheduleDesktopReminder(r){try{const res=await fetch('./api/reminders/schedule',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:r.id,title:r.title,body:r.note||`تذكير مرتبط بالقضية`,at:r.at,caseId:r.caseId})});return res.ok;}catch(_){return false;}}
async function unscheduleDesktopReminder(id){if(!appState.desktop)return;try{await fetch(`./api/reminders/${encodeURIComponent(id)}`,{method:'DELETE'});}catch(_){}}
window.deleteReminder=async id=>{if(!confirm('حذف التذكير؟'))return;await unscheduleDesktopReminder(id);await del('reminders',id);render();};
window.toggleReminder=async id=>{const r=await getOne('reminders',id);r.done=!r.done;if(r.done)await unscheduleDesktopReminder(id);else if(appState.desktop)r.scheduledDesktop=await scheduleDesktopReminder(r);await saveEntity('reminders',r);render();};
window.downloadReminderICS=async id=>{const r=await getOne('reminders',id),c=await getOne('cases',r.caseId);if(!r)return;const dt=new Date(r.at);const pad=n=>String(n).padStart(2,'0');const utc=d=>`${d.getUTCFullYear()}${pad(d.getUTCMonth()+1)}${pad(d.getUTCDate())}T${pad(d.getUTCHours())}${pad(d.getUTCMinutes())}${pad(d.getUTCSeconds())}Z`;const end=new Date(dt.getTime()+3600000);const safe=s=>String(s||'').replace(/([,;\\])/g,'\\$1').replace(/\n/g,'\\n');const ics=`BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//CasesManager//AR//EN\r\nBEGIN:VEVENT\r\nUID:${r.id}@cases-manager\r\nDTSTAMP:${utc(new Date())}\r\nDTSTART:${utc(dt)}\r\nDTEND:${utc(end)}\r\nSUMMARY:${safe(r.title)}\r\nDESCRIPTION:${safe((c?`قضية ${c.caseNumber}: ${c.subject}\\n`:'')+(r.note||''))}\r\nBEGIN:VALARM\r\nTRIGGER:-PT1H\r\nACTION:DISPLAY\r\nDESCRIPTION:${safe(r.title)}\r\nEND:VALARM\r\nEND:VEVENT\r\nEND:VCALENDAR\r\n`;downloadBlob(new Blob([ics],{type:'text/calendar;charset=utf-8'}),`تذكير_${slugName(r.title)}.ics`);};
window.requestNotifyPermission=async()=>{if(!('Notification'in window))return toast('المتصفح لا يدعم الإشعارات','error');const p=await Notification.requestPermission();toast(p==='granted'?'تم تفعيل إشعارات البرنامج':'لم يتم السماح بالإشعارات',p==='granted'?'success':'error');};
function startReminderWatcher(){if(notificationTimer)clearInterval(notificationTimer);notificationTimer=setInterval(checkReminders,30000);setTimeout(checkReminders,1500);}
async function checkReminders(){const rs=await getAll('reminders'),now=Date.now();for(const r of rs){if(r.done||r.firedAt||new Date(r.at).getTime()>now)continue;if(Notification.permission==='granted'){try{if(swReg)await swReg.showNotification(r.title,{body:r.note||'لديك تذكير مستحق',icon:'./icons/icon-192.png',data:{caseId:r.caseId}});else new Notification(r.title,{body:r.note||'لديك تذكير مستحق'});}catch(_){}}r.firedAt=nowISO();await put('reminders',r);} }

window.deleteEntity=async function(store,id){if(!confirm('حذف هذا السجل؟'))return;const o=await getOne(store,id);if(o)await softDelete(store,o);if(store==='sessions'||store==='actions'){const parentType=store==='sessions'?'session':'action';for(const a of (await getAll('attachments')).filter(x=>x.parentType===parentType&&x.parentId===id)){await del('attachments',a.id);}}render();};

function reportHTML(c,ctx){const ps=ctx.parties.filter(x=>x.caseId===c.id),ss=ctx.sessions.filter(x=>x.caseId===c.id).sort((a,b)=>new Date(a.dateTime||a.date)-new Date(b.dateTime||b.date)),as=ctx.actions.filter(x=>x.caseId===c.id).sort((a,b)=>new Date(a.date)-new Date(b.date)),fs=ctx.attachments.filter(x=>x.caseId===c.id);return `<!doctype html><html dir="rtl" lang="ar"><head><meta charset="utf-8"><title>قضية ${esc(c.caseNumber)}</title><style>body{font-family:Arial,Tahoma,sans-serif;direction:rtl;margin:30px;color:#111}h1{border-bottom:2px solid #111;padding-bottom:10px}h2{margin-top:25px;background:#eee;padding:8px}table{width:100%;border-collapse:collapse}td,th{border:1px solid #aaa;padding:8px;text-align:right;vertical-align:top}.muted{color:#666}.item{border:1px solid #aaa;padding:10px;margin:8px 0;page-break-inside:avoid}@media print{button{display:none}body{margin:12mm}}</style></head><body><h1>ملف قضية رقم ${esc(c.caseNumber)}</h1><table><tr><th>القطاع</th><td>${esc(sectorName(c.sectorId,ctx))}</td><th>السنة</th><td>${esc(c.year)}</td></tr><tr><th>الجهة المختصة</th><td>${esc(c.authority||'—')}</td><th>نوع القضية</th><td>${esc(caseTypeName(c.caseTypeId,ctx))}</td></tr><tr><th>تاريخ الورود</th><td>${fmtDate(c.receivedDate)}</td><th>الحالة</th><td>${statusText(c.status)}</td></tr><tr><th>الموضوع</th><td colspan="3">${esc(c.subject)}</td></tr><tr><th>ملاحظات</th><td colspan="3">${esc(c.notes||'—')}</td></tr></table><h2>الأطراف</h2>${ps.length?`<table><tr><th>الاسم</th><th>الصفة</th></tr>${ps.map(p=>`<tr><td>${esc(p.name)}</td><td>${esc(p.role)}</td></tr>`).join('')}</table>`:'<p>لا يوجد</p>'}<h2>الجلسات</h2>${ss.map(s=>`<div class="item"><b>${fmtDateTime(s.dateTime||s.date)}</b><p>${esc(s.summary||'')}</p><p><b>القرار:</b> ${esc(s.result||'—')}</p><p><b>التالي:</b> ${s.nextDate?fmtDateTime(s.nextDate):'—'}</p></div>`).join('')||'<p>لا يوجد</p>'}<h2>الإجراءات</h2>${as.map(a=>`<div class="item"><b>${esc(a.typeName||'إجراء')} — ${fmtDate(a.date)}</b><p>${esc(a.summary||'')}</p></div>`).join('')||'<p>لا يوجد</p>'}<h2>المرفقات</h2>${fs.length?`<table><tr><th>الاسم</th><th>الملف الأصلي</th><th>التصنيف</th><th>التاريخ</th></tr>${fs.map(f=>`<tr><td>${esc(f.label)}</td><td>${esc(f.originalName)}</td><td>${esc(f.category||'—')}</td><td>${fmtDate(f.fileDate||f.createdAt)}</td></tr>`).join('')}</table>`:'<p>لا يوجد</p>'}<p class="muted">تم إنشاء التقرير بواسطة نظام متابعة القضايا — ${new Date().toLocaleString('ar-EG')}</p></body></html>`;}
window.printCaseReport=async id=>{const ctx=await getContext(),c=ctx.cases.find(x=>x.id===id);if(!c)return;const html=reportHTML(c,ctx);if(appState.desktop){try{const r=await fetch('./api/pdf',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({filename:`قضية_${slugName(c.caseNumber)}.pdf`,html})});if(r.ok){downloadBlob(await r.blob(),`قضية_${slugName(c.caseNumber)}.pdf`);return;}}catch(e){console.warn(e);}}const w=window.open('','_blank');w.document.write(html);w.document.close();setTimeout(()=>w.print(),500);toast('اختر حفظ كـ PDF من شاشة الطباعة');};

// Minimal uncompressed ZIP writer for complete case packages.
const crcTable=(()=>{const t=[];for(let n=0;n<256;n++){let c=n;for(let k=0;k<8;k++)c=(c&1)?0xedb88320^(c>>>1):c>>>1;t[n]=c>>>0;}return t;})();
function crc32(u8){let c=0xffffffff;for(const b of u8)c=crcTable[(c^b)&255]^(c>>>8);return (c^0xffffffff)>>>0;}
function u16(n){return new Uint8Array([n&255,(n>>>8)&255]);} function u32(n){return new Uint8Array([n&255,(n>>>8)&255,(n>>>16)&255,(n>>>24)&255]);}
function concatU8(parts){let l=parts.reduce((a,b)=>a+b.length,0),o=new Uint8Array(l),p=0;for(const x of parts){o.set(x,p);p+=x.length;}return o;}
function dosDateTime(d=new Date()){let time=(d.getHours()<<11)|(d.getMinutes()<<5)|Math.floor(d.getSeconds()/2);let date=((d.getFullYear()-1980)<<9)|((d.getMonth()+1)<<5)|d.getDate();return {time,date};}
function makeZip(entries){const enc=new TextEncoder(),locals=[],centrals=[];let offset=0;for(const e of entries){const name=enc.encode(e.name.replace(/\\/g,'/')),data=e.data instanceof Uint8Array?e.data:new Uint8Array(e.data),crc=crc32(data),dt=dosDateTime();const local=concatU8([u32(0x04034b50),u16(20),u16(0x0800),u16(0),u16(dt.time),u16(dt.date),u32(crc),u32(data.length),u32(data.length),u16(name.length),u16(0),name,data]);locals.push(local);const cen=concatU8([u32(0x02014b50),u16(20),u16(20),u16(0x0800),u16(0),u16(dt.time),u16(dt.date),u32(crc),u32(data.length),u32(data.length),u16(name.length),u16(0),u16(0),u16(0),u16(0),u32(0),u32(offset),name]);centrals.push(cen);offset+=local.length;}const central=concatU8(centrals),body=concatU8(locals);const end=concatU8([u32(0x06054b50),u16(0),u16(0),u16(entries.length),u16(entries.length),u32(central.length),u32(body.length),u16(0)]);return concatU8([body,central,end]);}
window.exportCasePack=async id=>{const ctx=await getContext(),c=ctx.cases.find(x=>x.id===id);if(!c)return;toast('جارٍ تجهيز ملف القضية...');const entries=[{name:'تقرير_القضية.html',data:new TextEncoder().encode(reportHTML(c,ctx))}];const atts=ctx.attachments.filter(x=>x.caseId===id);for(const a of atts){try{const ab=await decryptAttachment(a);let folder='مرفقات_القضية';if(a.parentType==='session')folder='مرفقات_الجلسات';if(a.parentType==='action')folder='مرفقات_الإجراءات';entries.push({name:`${folder}/${slugName(a.label)}__${slugName(a.originalName)}`,data:new Uint8Array(ab)});}catch(e){console.warn('skip',a.id,e);}}const zip=makeZip(entries);downloadBlob(new Blob([zip],{type:'application/zip'}),`ملف_القضية_${slugName(c.caseNumber)}.zip`);toast('تم تجهيز ملف القضية الكامل','success');};

window.showBackup=()=>{const m=modal('النسخ الاحتياطي والاستيراد والدمج',`<div class="cards-list"><div class="item-card"><h4>تصدير نسخة احتياطية</h4><p>تتضمن القاعدة والمرفقات المشفرة وتُستخدم للنقل والدمج بين الكمبيوتر والـiPhone.</p><button class="btn primary" id="bk-export">تصدير قاعدة البيانات</button></div><div class="item-card"><h4>استيراد ودمج</h4><p>السجلات الجديدة تُضاف تلقائيًا، وأي اختلاف في نفس السجل يظهر في شاشة تعارض لاختيار النسخة الصحيحة.</p><input id="bk-file" class="input" type="file" accept=".casebackup,.json"><button style="margin-top:8px" class="btn" id="bk-import">استيراد ودمج</button></div><div class="item-card"><h4>معلومات النسخة</h4><p>App Version: ${APP_VERSION}<br>Database Schema: ${DB_VERSION}<br>Device ID: <span class="kbd">${esc(deviceId.slice(0,12))}</span></p></div></div>`,'<button class="btn" data-close>إغلاق</button>');$('#bk-export',m).onclick=exportBackup;$('#bk-import',m).onclick=()=>importBackup($('#bk-file',m).files?.[0]);};
async function exportBackup(){const payload={format:'CasesManagerBackup',version:1,appVersion:APP_VERSION,schemaVersion:DB_VERSION,createdAt:nowISO(),sourceDevice:deviceId,cryptoKey:await settingsGet('cryptoKey'),stores:{}};for(const s of entityStores)payload.stores[s]=await getAll(s);payload.stores.attachments=[];for(const a of await getAll('attachments')){payload.stores.attachments.push({...a,data:b64FromBuf(a.data)});}payload.stores.trash=await getAll('trash');downloadBlob(new Blob([JSON.stringify(payload)],{type:'application/json'}),`CasesBackup_${new Date().toISOString().slice(0,10)}.casebackup`);await settingsSet('lastBackupAt',nowISO());toast('تم تصدير النسخة الاحتياطية','success');}
async function importBackup(file){
  if(!file)return toast('اختر ملف النسخة الاحتياطية','error');
  let p;try{p=JSON.parse(await file.text());}catch(_){return toast('ملف غير صالح','error');}
  if(p.format!=='CasesManagerBackup'||!p.stores)return toast('صيغة النسخة غير معروفة','error');
  let sourceKey=null;try{sourceKey=await crypto.subtle.importKey('raw',bufFromB64(p.cryptoKey),'AES-GCM',true,['decrypt']);}catch(_){return toast('تعذر قراءة مفتاح المرفقات في النسخة','error');}
  const conflicts=[];
  const caseIdMap=new Map();

  // Merge sectors and editable lookup lists first.
  for(const store of ['sectors','caseTypes','actionTypes']){
    const incoming=p.stores[store]||[], local=await getAll(store), map=new Map(local.map(x=>[x.id,x]));
    for(const x0 of incoming){const x=structuredClone(x0), l=map.get(x.id); if(!l)await put(store,x); else if(deepComparable(l)!==deepComparable(x)) conflicts.push({store,local:l,incoming:x});}
  }

  // Case numbers are globally unique. Same number with a different UUID is treated as the same logical case.
  const localCases=await getAll('cases'), byId=new Map(localCases.map(x=>[x.id,x])), byNumber=new Map(localCases.map(x=>[String(x.caseNumber),x]));
  for(const x0 of p.stores.cases||[]){
    const x=structuredClone(x0); let l=byId.get(x.id);
    if(!l) l=byNumber.get(String(x.caseNumber));
    if(!l){await put('cases',x); caseIdMap.set(x.id,x.id); byId.set(x.id,x); byNumber.set(String(x.caseNumber),x);}
    else {caseIdMap.set(x.id,l.id); if(deepComparable(l)!==deepComparable(x)) conflicts.push({store:'cases',local:l,incoming:{...x,id:l.id}});}
  }

  // Child records keep the local case UUID when the same case existed independently on both devices.
  for(const store of ['parties','sessions','actions','reminders','timeline']){
    const incoming=p.stores[store]||[], local=await getAll(store), map=new Map(local.map(x=>[x.id,x]));
    for(const x0 of incoming){const x=structuredClone(x0); if(x.caseId&&caseIdMap.has(x.caseId))x.caseId=caseIdMap.get(x.caseId); const l=map.get(x.id);if(!l)await put(store,x);else if(deepComparable(l)!==deepComparable(x))conflicts.push({store,local:l,incoming:x});}
  }

  const localAtts=await getAll('attachments'); const attById=new Map(localAtts.map(x=>[x.id,x])), attByHash=new Map(localAtts.filter(x=>x.hash).map(x=>[x.hash,x]));
  for(const inc0 of p.stores.attachments||[]){
    const incoming={...inc0,data:bufFromB64(inc0.data)}; if(incoming.caseId&&caseIdMap.has(incoming.caseId))incoming.caseId=caseIdMap.get(incoming.caseId); if(incoming.parentType==='case'&&caseIdMap.has(incoming.parentId))incoming.parentId=caseIdMap.get(incoming.parentId);
    const l=attById.get(incoming.id)||attByHash.get(incoming.hash);
    if(!l){try{const plain=await decryptAttachment(incoming,sourceKey),enc=await encryptBuffer(plain);incoming.iv=enc.iv;incoming.data=enc.data;await put('attachments',incoming);}catch(e){console.warn(e);}}
    else if(l.hash!==incoming.hash||l.label!==incoming.label||l.category!==incoming.category){conflicts.push({store:'attachments',local:l,incoming,sourceKey});}
  }
  for(const c of conflicts)await resolveConflict(c);
  toast(`تم الدمج${conflicts.length?` ومعالجة ${conflicts.length} تعارض`:''}`,'success');render();
}
function prettyForConflict(x){const c={...x};if(c.data)c.data=`[بيانات ملف ${bytesFmt(c.size)}]`;return JSON.stringify(c,null,2);}
async function resolveConflict(c){return new Promise(resolve=>{const m=modal(`تعارض في ${c.store}`,`<p class="muted">السجل موجود بنسختين مختلفتين. اختر النسخة التي تريد الاحتفاظ بها.</p><div class="conflict-grid"><div class="conflict-box"><b>نسخة هذا الجهاز</b><pre>${esc(prettyForConflict(c.local))}</pre></div><div class="conflict-box"><b>النسخة المستوردة</b><pre>${esc(prettyForConflict(c.incoming))}</pre></div></div>`,`<button class="btn" id="cf-local">الاحتفاظ بنسخة الجهاز</button><button class="btn primary" id="cf-in">استخدام النسخة المستوردة</button>`,true);$('#cf-local',m).onclick=()=>{m.remove();resolve();};$('#cf-in',m).onclick=async()=>{let x=c.incoming;if(c.store==='attachments'&&c.sourceKey){const plain=await decryptAttachment(x,c.sourceKey),enc=await encryptBuffer(plain);x={...x,iv:enc.iv,data:enc.data};}await put(c.store,x);m.remove();resolve();};});}

boot().catch(e=>{console.error(e);document.body.innerHTML=`<pre style="direction:ltr;color:white;padding:20px">${esc(e.stack||e.message)}</pre>`;});
